// the decision core: sealed, no I/O, no state that outlives one decision
public sealed class ReferenceMonitor(IPolicyStore store) : IReferenceMonitor
{
    public async ValueTask<Decision> CheckAsync(ClaimsPrincipal user, Action action, ObjectId id)
    {
        var principal = user.Identity?.Name;                 // absent identity => deny
        if (principal is null) return Decision.Deny("no principal");
        var rule = await store.FindAsync(principal, action, id);
        return rule?.Allow == true ? Decision.Allow : Decision.Deny("no rule");   // fail closed
    }
}
